import{_ as a,a0 as l,w as s,s as u,I as o,x as e,a1 as n,A as i,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"试试这个 Linux 网络浏览器作为你的文件管理器 | LCTT x X-CMD","titleTemplate":false,"description":"试试这个 Linux 网络浏览器作为你的文件管理器 | LCTT (202212) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"试试这个 Linux 网络浏览器作为你的文件管理器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"试试这个 Linux 网络浏览器作为你的文件管理器 | LCTT (202212) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202212/20221213.6 ⭐️⭐️ Try this Linux web browser as your file manager","title":"试试这个 Linux 网络浏览器作为你的文件管理器","tag":"202212","desc":""},"relativePath":"202212/20221213.6 ⭐️⭐️ Try this Linux web browser as your file manager.md","filePath":"[post].md"}'),d={name:"202212/20221213.6 ⭐️⭐️ Try this Linux web browser as your file manager.md"};function m(b,r,h,g,f,k){const t=l("Link");return s(),u("div",null,[r[20]||(r[20]=o("h1",{id:"试试这个-linux-网络浏览器作为你的文件管理器",tabindex:"-1"},[e("试试这个 Linux 网络浏览器作为你的文件管理器 "),o("a",{class:"header-anchor",href:"#试试这个-linux-网络浏览器作为你的文件管理器","aria-label":"Permalink to “试试这个 Linux 网络浏览器作为你的文件管理器”"},"​")],-1)),r[21]||(r[21]=o("p",null,[o("img",{src:"https://img.linux.net.cn/data/attachment/album/202212/29/141332adtz8mb8m8h8z3d4.jpg",alt:""})],-1)),r[22]||(r[22]=o("blockquote",null,[o("p",null,"KDE Plasma 桌面将 Konqueror 列为网络浏览器，但它也是一个功能性的 Linux 文件管理器。")],-1)),r[23]||(r[23]=o("p",null,"Konqueror 是 KDE Plasma 桌面的文件管理器和 Web 浏览器。在许多方面，Konqueror 定义了“网络透明度”，因为它适用于个人桌面。使用 Konqueror，你可以像浏览本地文件一样轻松地浏览远程网络文件（包括互联网本身，它实际上只是通过花哨的镜头查看的远程文件的集合）。有时需要进行一些配置和设置，具体取决于你需要访问的文件共享类型。但最终，通过 Konqueror 实现了即时访问你有权查看的所有数据的目标，这是其他文件管理器无法实现的。在其巅峰时期，它开发的开源网络引擎（KHTML） 被苹果和谷歌采用，并作为现代网络浏览和 Electron 应用开发的核心库延续至今。",-1)),o("p",null,[r[2]||(r[2]=e("今天，KDE Plasma 桌面将 Konqueror 作为网络浏览器。文件管理功能已正式转移到 ",-1)),n(t,{href:"https://opensource.com/article/22/12/linux-file-manager-dolphin"},{default:i(()=>[...r[0]||(r[0]=[e("Dolphin",-1)])]),_:1}),r[3]||(r[3]=e("，但 Konqueror 仍然能够完成这项工作。要获得完整和经典的 Konqueror 体验，你应该尝试 Plasma 桌面 3.x 的复刻 ",-1)),n(t,{href:"https://opensource.com/article/19/12/linux-trinity-desktop-environment-tde"},{default:i(()=>[...r[1]||(r[1]=[e("TDE",-1)])]),_:1}),r[4]||(r[4]=e("，但在本文中，我在 KDE Plasma 桌面版本 5 中使用 Konqueror。",-1))]),r[24]||(r[24]=p('<h3 id="安装-konqueror" tabindex="-1">安装 Konqueror <a class="header-anchor" href="#安装-konqueror" aria-label="Permalink to “安装 Konqueror”">​</a></h3><p>如果你已经在运行 KDE Plasma 桌面，你可能已经安装了 Konqueror。如果没有，你可以从发行版软件仓库中安装它。在 Fedora、CentOS、Mageia、OpenMandriva 和类似软件上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install -y konqueror konqueror-plugins</span></span></code></pre></div><p>在 Debian、Linux Mint、Elementary 和类似软件上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install -y konqueror konqueror-plugins</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/2022-10/konqueror-filemanager.png" alt="Image of Konqueror&#39;s file manager."></p><h3 id="将-konqueror-配置为文件管理器" tabindex="-1">将 Konqueror 配置为文件管理器 <a class="header-anchor" href="#将-konqueror-配置为文件管理器" aria-label="Permalink to “将 Konqueror 配置为文件管理器”">​</a></h3><p>Konqueror 最方便的功能是它除了是一个文件管理器之外，还是一个网络浏览器。至少，这在理论上是它最方便的功能。如果你没有将 Konqueror 用作网络浏览器，那么你可能不希望每个文件管理器窗口顶部都有 URL 区域或搜索引擎区域。</p><p>与大多数 KDE 应用一样，Konqueror 是高度可配置的。你可以重新定位并添加和删除工具栏、添加或删除按钮等。</p><p>要调整显示的工具栏，请启动 Konqueror 并转到 “<ruby>设置<rt>Settings</rt></ruby>” 菜单并选择 “<ruby>显示的工具栏<rt>Toolbars Shown</rt></ruby>”。主工具栏可能是你真正需要的文件管理工具栏。它是带有导航按钮的工具栏。但是，你甚至可能不需要它，只要你乐于使用键盘快捷键或使用 “Go” 菜单进行导航即可。</p><p>Konqueror 中的键盘导航与 Dolphin 中的相同：</p><ul><li><code>Alt + ←</code>：后退一步</li><li><code>Alt + ↑</code>：移动到父目录</li><li><code>Alt + Home</code>：转到主目录</li></ul><h3 id="侧边栏" tabindex="-1">侧边栏 <a class="header-anchor" href="#侧边栏" aria-label="Permalink to “侧边栏”">​</a></h3><p>要获得包含常用文件夹列表的侧边栏，请按 <code>F9</code> 或从 “<ruby>设置<rt>Settings</rt></ruby>” 菜单中选择 “<ruby>显示边栏<rt>Show Sidebar</rt></ruby>”。这会在 Konqueror 窗口的左侧添加一个按钮栏。单击 “Home” 图标以显示你的主目录的文件树。</p><p><img src="https://opensource.com/sites/default/files/2022-10/konqueror-sidebar.png" alt="Image of Konqueror with a sidebar."></p><p>正如按钮栏所暗示的那样，此侧边栏可用于多种用途。你可以显示书签位置，你最近访问过的位置的历史，远程文件系统等。</p><h3 id="应用" tabindex="-1">应用 <a class="header-anchor" href="#应用" aria-label="Permalink to “应用”">​</a></h3><p>有些人习惯于应用菜单。它高效快捷，并且始终在同一个地方。其他人更喜欢从终端启动应用。</p><p>不过，还有另一种查看应用启动器的方法。Konqueror 的 “Go” 菜单允许你转到名为 “<ruby>应用程序<rt>Applications</rt></ruby>” 的元位置，它按类别列出了应用程序启动器，就像文件管理器中的文件一样。</p><p><img src="https://opensource.com/sites/default/files/2022-10/konqueror-applications.png" alt="Image of applications in Konqueror."></p><p>你也可以在 Dolphin 中看到这个，方法是在位置区域中手动输入 <code>applications:</code>，此外，Konqueror 提供了一个菜单选项，可以直接进入该位置。</p><h3 id="网络文件夹" tabindex="-1">网络文件夹 <a class="header-anchor" href="#网络文件夹" aria-label="Permalink to “网络文件夹”">​</a></h3><p>类似地，Konqueror 还提供了一个菜单选择进入网络文件夹。其中最好的网络文件夹是“互联网”，但“网络文件夹”是 HTTP 以外的网络协议的元位置。大多数远程位置需要一些设置，因为它们通常需要身份验证才能访问。它们中的大多数都可以通过 “<ruby>系统设置<rt>System Settings</rt></ruby>” 进行配置，包括可通过蓝牙、SMB 或 CIFS、MTP 设备、Fish（通过 SSH 的文件系统）访问的文件系统，甚至是 Google Drive。</p><h3 id="拆分视图" tabindex="-1">拆分视图 <a class="header-anchor" href="#拆分视图" aria-label="Permalink to “拆分视图”">​</a></h3><p>你可以将 Konqueror 窗口拆分为多个窗格，这样你就可以同时查看两个文件夹而无需打开两个窗口。有两种拆分选项：垂直拆分，一个窗格在左侧，另一个窗格在右侧；或者水平拆分，一个窗格在另一个窗格之上。</p><p>要分割 Konqueror 窗口，进入 “<ruby>窗口<rt>Window</rt></ruby>” 菜单，选择 “<ruby>左/右分割视图<rt>Split View Left/Right</rt></ruby>” 或 “<ruby>上/下分割视图<rt>Spit View Top/Bottom</rt></ruby>”。每个窗格都是独立的，所以你可以在一个窗格中浏览，然后把文件从一个窗格拖到另一个窗格。</p><h3 id="征服你的文件系统" tabindex="-1">征服你的文件系统 <a class="header-anchor" href="#征服你的文件系统" aria-label="Permalink to “征服你的文件系统”">​</a></h3><p>Konqueror 不 <em>仅仅</em> 是一个文件管理器，我认为 Plasma 桌面的开发者并不期望你把它作为你的主要文件管理器。在 “<ruby>文件<rt>File</rt></ruby>” 菜单中甚至有一个选项可以在 <strong>Dolphin</strong> 中打开一个位置，这表明 Konqueror 是一个带有文件管理器组件的网络浏览器。但是，当你需要时，这个文件管理器组件是一个不错的功能。如果你不喜欢 Dolphin 提供的所有功能，Konqueror 可能是一个合适的替代品。</p><hr>',29)),o("p",null,[r[6]||(r[6]=e("via: ",-1)),n(t,{href:"https://opensource.com/article/22/12/linux-file-manager-konqueror"},{default:i(()=>[...r[5]||(r[5]=[e("https://opensource.com/article/22/12/linux-file-manager-konqueror",-1)])]),_:1})]),o("p",null,[r[11]||(r[11]=e("作者：",-1)),n(t,{href:"https://opensource.com/users/seth"},{default:i(()=>[...r[7]||(r[7]=[e("Seth Kenlon",-1)])]),_:1}),r[12]||(r[12]=e(" 选题：",-1)),n(t,{href:"https://github.com/lkxed"},{default:i(()=>[...r[8]||(r[8]=[e("lkxed",-1)])]),_:1}),r[13]||(r[13]=e(" 译者：",-1)),n(t,{href:"https://github.com/geekpi"},{default:i(()=>[...r[9]||(r[9]=[e("geekpi",-1)])]),_:1}),r[14]||(r[14]=e(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:i(()=>[...r[10]||(r[10]=[e("wxy",-1)])]),_:1})]),o("p",null,[r[17]||(r[17]=e("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...r[15]||(r[15]=[e("LCTT",-1)])]),_:1}),r[18]||(r[18]=e(" 原创编译，",-1)),n(t,{href:"https://linux.cn/"},{default:i(()=>[...r[16]||(r[16]=[e("Linux中国",-1)])]),_:1}),r[19]||(r[19]=e(" 荣誉推出",-1))])])}const K=a(d,[["render",m]]);export{y as __pageData,K as default};
